"""specs_s200028.py - Sonnet-w2 family E (generated by mkfamDE.py). Hooks record the SEH chain (seh_record) and the registers/args; fake outer SEH records 0-2; fs:[0] compared.
The engine table byte at +0xbad is zero or non-zero. For E the fastcall sibling hook also records edx."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _mk(init, sib):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x400), rnd(c, 0x400), rnd(c, 0x400)])
        hook_rec(c, 0x45c4f0, 2, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, 0x45c4b0, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, 0x45c3a0, 3, ret=r.getrandbits(32), pop=12, this=True, side=seh_record(c, 2))
        if sib:
            sr = seh_record(c, 2)

            def side(emu, k):
                emu.calllog.append(('edx', emu.reg('edx')))
                sr(emu, k)
            hook_rec(c, sib, 2, ret=r.getrandbits(32), pop=8, this=True, side=side)
        eng = rnd(c, 0x1b00)
        c.emu.w32(0x70039c, eng)
        t = rnd(c, 0xc00)
        c.emu.w32(eng + 0x9b, t)
        c.emu.wbytes(t + 0xbad, bytes([r.choice([0, 0, 1, r.randrange(256)])]))
        return [r.getrandbits(32), r.getrandbits(32), r.getrandbits(32), r.choice([0, 0, 1, r.getrandbits(32)]) if True else r.getrandbits(32)]
    return gen


S(0x447d20, 'GUESS famE 0x447d20', 'fastcall', None, ret='eax', gen=_mk(0, 0x446f30), note='batch200028')
